# ==========================================
# Global Helper Functions
# ==========================================
get_mode <- function(v) {
  uniqv <- unique(v)
  tab <- tabulate(match(v, uniqv))
  max_count <- max(tab)
  modes <- uniqv[tab == max_count]
  paste(modes, collapse = ", ")
}

fmt <- function(x) ifelse(is.na(x) | is.nan(x) | is.infinite(x), "", sprintf("%.4f", as.numeric(x)))
p_fmt <- function(x) {
  if(is.na(x) || is.nan(x)) return("")
  ifelse(as.numeric(x) < 0.0001, "< 0.0001", sprintf("%.4f", as.numeric(x)))
}

ch71_fmt <- function(x) ifelse(is.na(x) | is.nan(x) | is.infinite(x), "#DIV/0!", sprintf("%.4f", x))
ch71_p_fmt <- function(x) {
  if(is.na(x) || is.nan(x)) return("#DIV/0!")
  ifelse(x < 0.0001, "< 0.0001", sprintf("%.4f", x))
}
ch71_get_es_size <- function(val, type="d") {
  if(is.na(val) || is.nan(val) || is.infinite(val)) return("#DIV/0!")
  v <- abs(val)
  if(type %in% c("d", "g", "delta", "h")) {
    if(v >= 0.8) return("Large")
    if(v >= 0.5) return("Moderate")
    return("Small")
  } else {
    if(v >= 0.5) return("Large")
    if(v >= 0.3) return("Moderate")
    return("Small")
  }
}

runs_test_custom <- function(x) {
  x_bin <- as.numeric(x > median(x)); n1 <- sum(x_bin == 1); n2 <- sum(x_bin == 0); runs <- 1
  if(length(x_bin) > 1) { for(i in 2:length(x_bin)) { if(x_bin[i] != x_bin[i-1]) runs <- runs + 1 } }
  mu <- (2 * n1 * n2) / (n1 + n2) + 1; var <- (2 * n1 * n2 * (2 * n1 * n2 - n1 - n2)) / ((n1 + n2)^2 * (n1 + n2 - 1))
  if(var <= 0 || is.na(var)) return(list(runs = runs, z = NA, p = NA))
  z <- (runs - mu) / sqrt(var); p_val <- 2 * (1 - pnorm(abs(z)))
  return(list(runs = runs, z = z, p = p_val))
}

