# Define Server Logic
# ==========================================
server <- function(input, output, session) {
  
  # ==========================================
  # Navigation Logic (INDEX)
  # ==========================================
  observeEvent(input$link_2_1, { updateNavbarPage(session, "main_nav", selected = "tab_2_1") })
  observeEvent(input$link_2_2, { updateNavbarPage(session, "main_nav", selected = "tab_2_2") })
  observeEvent(input$link_3, { updateNavbarPage(session, "main_nav", selected = "tab_3") })
  observeEvent(input$link_4_1, { updateNavbarPage(session, "main_nav", selected = "tab_4_1") })
  observeEvent(input$link_4_2, { updateNavbarPage(session, "main_nav", selected = "tab_4_2") })
  observeEvent(input$link_4_3, { updateNavbarPage(session, "main_nav", selected = "tab_4_3") })
  observeEvent(input$link_5, { updateNavbarPage(session, "main_nav", selected = "tab_5") })
  observeEvent(input$link_6_1, { updateNavbarPage(session, "main_nav", selected = "tab_6_1") })
  observeEvent(input$link_6_2, { updateNavbarPage(session, "main_nav", selected = "tab_6_2") })
  observeEvent(input$link_7_1, { updateNavbarPage(session, "main_nav", selected = "tab_7_1") })
  observeEvent(input$link_7_2, { updateNavbarPage(session, "main_nav", selected = "tab_7_2") })
  observeEvent(input$link_8_2, { updateNavbarPage(session, "main_nav", selected = "tab_8_2") })
  observeEvent(input$link_8_3, { updateNavbarPage(session, "main_nav", selected = "tab_8_3") })
  observeEvent(input$link_9, { updateNavbarPage(session, "main_nav", selected = "tab_9") })
  observeEvent(input$link_10, { updateNavbarPage(session, "main_nav", selected = "tab_10") })
  observeEvent(input$link_11_4, { updateNavbarPage(session, "main_nav", selected = "tab_11_4") })
  
  # ==========================================
  # CHAPTER 2
  # ==========================================
  data_reactive_21 <- reactive({ cleaned_input <- gsub("[,\\n]", " ", input$frequencies_21); split_input <- unlist(strsplit(trimws(cleaned_input), "\\s+")); frequencies <- as.numeric(split_input); frequencies <- frequencies[!is.na(frequencies)]; if (length(frequencies) == 0) return(NULL); classes <- as.character(1:length(frequencies)); df <- data.frame(Class = factor(classes, levels = classes), Frequency = frequencies); total_freq <- sum(df$Frequency, na.rm = TRUE); df <- df %>% mutate(`Cumulative Frequency` = cumsum(Frequency), `Relative Frequency` = Frequency / total_freq, `Relative Frequency %` = `Relative Frequency`, `Cumulative Relative Frequency` = cumsum(`Relative Frequency`), `Cumulative Relative Frequency %` = `Cumulative Relative Frequency`); return(df) })
  output$summary_table_21 <- renderDT({ df <- data_reactive_21(); if (is.null(df)) return(datatable(data.frame(Error="Please enter valid numeric frequencies."))); total_row <- data.frame(Class = "Total", Frequency = sum(df$Frequency), `Cumulative Frequency` = max(df$`Cumulative Frequency`), `Relative Frequency` = sum(df$`Relative Frequency`), `Relative Frequency %` = sum(df$`Relative Frequency %`), `Cumulative Relative Frequency` = 1.0, `Cumulative Relative Frequency %` = 1.0, check.names = FALSE); datatable(rbind(df, total_row), options = list(pageLength = 20, dom = 't')) %>% formatPercentage(c('Relative Frequency %', 'Cumulative Relative Frequency %'), 2) %>% formatRound(c('Relative Frequency', 'Cumulative Relative Frequency'), 4) })
  output$barChart_21 <- renderPlot({ df <- data_reactive_21(); if(is.null(df)) return(NULL); ggplot(df, aes(x=Class, y=Frequency, fill=Class)) + geom_bar(stat="identity", show.legend=FALSE) + theme_minimal() + labs(title="Frequency Bar Chart", x="Class", y="Frequency") + geom_text(aes(label=Frequency), vjust=-0.3) })
  output$pieChart_21 <- renderPlot({ df <- data_reactive_21(); if(is.null(df)) return(NULL); ggplot(df, aes(x="", y=Frequency, fill=Class)) + geom_bar(stat="identity", width=1) + coord_polar("y", start=0) + theme_void() + labs(title="Relative Frequency Pie Chart") + geom_text(aes(label=percent(`Relative Frequency`)), position=position_stack(vjust=0.5)) })
  output$paretoChart_21 <- renderPlot({ df <- data_reactive_21(); if(is.null(df)) return(NULL); ggplot(df, aes(x=Class, y=`Relative Frequency`, fill=Class)) + geom_bar(stat="identity", show.legend=FALSE) + scale_y_continuous(labels=scales::percent) + theme_minimal() + labs(title="Relative Frequency Bar Chart", x="Class", y="Relative Frequency (%)") })
