  output$ch42_poi_prob_table <- renderDT({ req(input$ch42_poi_mean1, input$ch42_poi_x1); lam <- input$ch42_poi_mean1; x <- input$ch42_poi_x1; datatable(data.frame(Result=c("\"=\"", "\"<\"", "\"≤\"", "\">\"", "\"≥\""), Prob=c(fmt(dpois(x,lam)), fmt(ppois(x-1,lam)), fmt(ppois(x,lam)), fmt(1-ppois(x,lam)), fmt(1-ppois(x-1,lam)))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch42_poi_between_table <- renderDT({ req(input$ch42_poi_mean2, input$ch42_poi_xl, input$ch42_poi_xu); lam <- input$ch42_poi_mean2; xL <- input$ch42_poi_xl; xU <- input$ch42_poi_xu; datatable(data.frame(Result=c("\"(xL < x < xU)\"", "\"(xL ≤ x < xU)\"", "\"(xL < x ≤ xU)\"", "\"(xL ≤ x ≤ xU)\""), Prob=c(fmt(max(0, ppois(xU-1,lam)-ppois(xL,lam))), fmt(max(0, ppois(xU-1,lam)-ppois(xL-1,lam))), fmt(max(0, ppois(xU,lam)-ppois(xL,lam))), fmt(max(0, ppois(xU,lam)-ppois(xL-1,lam))))), options=list(dom='t', ordering=F), rownames=F) })
