  ch83_plot_lsmeans <- function(mod, spec, x_var, color_var=NULL) {
    f_spec <- as.formula(paste("~", spec)); em <- as.data.frame(emmeans(mod, specs=f_spec)); x_col <- paste0("`", x_var, "`")
    p <- ggplot(em, aes_string(x=x_col, y="emmean")) + theme_bw() + labs(y="Least Squares Mean") + theme(plot.title=element_text(hjust=0.5, face="bold"))
    if(is.null(color_var)) { p <- p + geom_errorbar(aes(ymin=lower.CL, ymax=upper.CL), width=0.2) + geom_point(size=3, color="steelblue", shape=15) + geom_line(aes(group=1), color="steelblue", linetype="dashed") } else { c_col <- paste0("`", color_var, "`"); p <- p + geom_errorbar(aes_string(ymin="lower.CL", ymax="upper.CL", color=c_col), width=0.2, position=position_dodge(0.2)) + geom_point(aes_string(color=c_col), size=3, shape=15, position=position_dodge(0.2)) + geom_line(aes_string(group=c_col, color=c_col), position=position_dodge(0.2), linetype="dashed") }
    return(p)
  }
