  ch83_get_custom_pairwise <- function(mod, df_data, spec, by_var=NULL) {
    alpha <- input$ch83_alpha; adj_method <- input$ch83_adj_method
    if(is.null(by_var)) {
      f_spec <- as.formula(paste("~", paste0("`", spec, "`"))); em_obj <- emmeans(mod, specs=f_spec); pw <- as.data.frame(pairs(em_obj, adjust="none")); lvl <- levels(em_obj@grid[[spec]]); if(is.null(lvl)) lvl <- unique(em_obj@grid[[spec]])
      ns <- sapply(lvl, function(x) sum(df_data[[spec]]==x, na.rm=TRUE)); pairs_idx <- combn(length(lvl), 2); custom_dfs <- numeric(ncol(pairs_idx)); for(i in 1:ncol(pairs_idx)) { custom_dfs[i] <- ns[pairs_idx[1,i]] + ns[pairs_idx[2,i]] - 2 }; m <- length(custom_dfs); ts <- pw$t.ratio; diffs <- pw$estimate; ses <- pw$SE; unadj_p <- 2*(1-pt(abs(ts), custom_dfs))
      if(adj_method=="bonferroni") { adj_p <- p.adjust(unadj_p, method="bonferroni"); t_crit_adjs <- qt(1-alpha/(2*m), custom_dfs) } else if(adj_method=="holm") { adj_p <- p.adjust(unadj_p, method="holm"); t_crit_adjs <- qt(1-alpha/(2*m), custom_dfs) } else if(adj_method=="tukey") { k_total <- length(lvl); adj_p <- ptukey(abs(ts)*sqrt(2), k_total, custom_dfs, lower.tail=FALSE); t_crit_adjs <- qtukey(1-alpha, k_total, custom_dfs)/sqrt(2) } else { adj_p <- unadj_p; t_crit_adjs <- qt(1-alpha/2, custom_dfs) }
      adj_lcl <- diffs - t_crit_adjs * ses; adj_ucl <- diffs + t_crit_adjs * ses
      out_df <- data.frame(Comparison=pw$contrast, Difference=fmt(diffs), `SE(Diff)`=fmt(ses), `t-value`=fmt(ts), df=fmt(custom_dfs), `Unadjusted p-value`=p_fmt(unadj_p), `Adj LCL`=fmt(adj_lcl), `Adj UCL`=fmt(adj_ucl), `Adjusted p-value`=p_fmt(adj_p), check.names=FALSE)
    } else {
      f_spec <- as.formula(paste("pairwise ~", paste0("`", spec, "`"), "|", paste0("`", by_var, "`"))); em_res <- emmeans(mod, specs=f_spec); pw <- as.data.frame(em_res$contrasts); em_obj <- em_res$emmeans; lvl_spec <- levels(em_obj@grid[[spec]]); if(is.null(lvl_spec)) lvl_spec <- unique(em_obj@grid[[spec]]); lvl_by <- levels(em_obj@grid[[by_var]]); if(is.null(lvl_by)) lvl_by <- unique(em_obj@grid[[by_var]]); pairs_idx <- combn(length(lvl_spec), 2); num_pairs <- ncol(pairs_idx); custom_dfs <- numeric(nrow(pw)); row_idx <- 1
      for(b in lvl_by) { ns <- sapply(lvl_spec, function(x) sum(df_data[[spec]]==x & df_data[[by_var]]==b, na.rm=TRUE)); for(i in 1:num_pairs) { custom_dfs[row_idx] <- ns[pairs_idx[1,i]] + ns[pairs_idx[2,i]] - 2; row_idx <- row_idx + 1 } }
      ts <- pw$t.ratio; diffs <- pw$estimate; ses <- pw$SE; unadj_p <- 2*(1-pt(abs(ts), custom_dfs)); adj_p <- numeric(nrow(pw)); t_crit_adjs <- numeric(nrow(pw)); row_idx <- 1
      for(b in lvl_by) {
        idx <- row_idx:(row_idx + num_pairs - 1); m_sub <- num_pairs; p_sub <- unadj_p[idx]; t_sub <- ts[idx]; df_sub <- custom_dfs[idx]
        if(adj_method=="bonferroni") { adj_p[idx] <- p.adjust(p_sub, method="bonferroni"); t_crit_adjs[idx] <- qt(1-alpha/(2*m_sub), df_sub) } else if(adj_method=="holm") { adj_p[idx] <- p.adjust(p_sub, method="holm"); t_crit_adjs[idx] <- qt(1-alpha/(2*m_sub), df_sub) } else if(adj_method=="tukey") { k_sub <- length(lvl_spec); adj_p[idx] <- ptukey(abs(t_sub)*sqrt(2), k_sub, df_sub, lower.tail=FALSE); t_crit_adjs[idx] <- qtukey(1-alpha, k_sub, df_sub)/sqrt(2) } else { adj_p[idx] <- p_sub; t_crit_adjs[idx] <- qt(1-alpha/2, df_sub) }
        row_idx <- row_idx + num_pairs
      }
      adj_lcl <- diffs - t_crit_adjs * ses; adj_ucl <- diffs + t_crit_adjs * ses
      out_df <- data.frame(Comparison=paste0("[", pw[[by_var]], "] ", pw$contrast), Difference=fmt(diffs), `SE(Diff)`=fmt(ses), `t-value`=fmt(ts), df=fmt(custom_dfs), `Unadjusted p-value`=p_fmt(unadj_p), `Adj LCL`=fmt(adj_lcl), `Adj UCL`=fmt(adj_ucl), `Adjusted p-value`=p_fmt(adj_p), check.names=FALSE)
    }
    prefix <- switch(adj_method, "bonferroni"="Bon-Adj", "tukey"="Tukey-Adj", "holm"="Holm-Adj", "none"="Unadj"); colnames(out_df)[7:8] <- c(paste(prefix, "LCL"), paste(prefix, "UCL")); return(out_df)
  }
