  output$ch9_diag_table <- renderTable({ req(ch9_reg_data()); mod <- ch9_reg_data()$model; df <- ch9_reg_data()$df; dw <- lmtest::dwtest(mod); white <- lmtest::bptest(mod, ~ X + I(X^2), data = df); shapiro <- shapiro.test(resid(mod)); runs <- randtests::runs.test(resid(mod), threshold = 0); data.frame(Test=c("Durbin-Watson", "White Test", "Shapiro-Wilks", "Runs Test"), Statistic=c(dw$statistic, white$statistic, shapiro$statistic, runs$statistic), `p-value`=c(dw$p.value, white$p.value, shapiro$p.value, runs$p.value), check.names=FALSE) }, digits=4)
  output$ch9_pred_table <- renderTable({ req(ch9_reg_data()); mod <- ch9_reg_data()$model; target_x <- data.frame(X = input$ch9_target_x); alpha <- input$ch9_ci_level / 100; ci_pred <- predict(mod, newdata = target_x, interval = "confidence", level = alpha); pi_pred <- predict(mod, newdata = target_x, interval = "prediction", level = alpha); data.frame(Type=c("Estimated Y", "Confidence Interval", "Prediction Interval"), Value=c(ci_pred[1, "fit"], NA, NA), Lower=c(NA, ci_pred[1, "lwr"], pi_pred[1, "lwr"]), Upper=c(NA, ci_pred[1, "upr"], pi_pred[1, "upr"])) }, na="", digits=4)
  ch9_corr_ci_res <- reactive({ req(input$ch9_r_val, input$ch9_n_val, input$ch9_ci_corr); r <- input$ch9_r_val; n <- input$ch9_n_val; conf <- input$ch9_ci_corr / 100; z_r <- 0.5 * log((1 + r) / (1 - r)); se <- 1 / sqrt(n - 3); z_crit <- qnorm(1 - (1 - conf) / 2); ll_z <- z_r - z_crit * se; ul_z <- z_r + z_crit * se; data.frame(Metric=c("z(r)", "LL (Z)", "UL (Z)", "LCL (r)", "UCL (r)"), Value=c(z_r, ll_z, ul_z, tanh(ll_z), tanh(ul_z))) })
  output$ch9_corr_ci_table <- renderTable({ ch9_corr_ci_res() }, digits=4)
  ch9_corr_comp_res <- reactive({ req(input$ch9_r1, input$ch9_n1, input$ch9_r2, input$ch9_n2); z1 <- 0.5 * log((1 + input$ch9_r1) / (1 - input$ch9_r1)); z2 <- 0.5 * log((1 + input$ch9_r2) / (1 - input$ch9_r2)); se_diff <- sqrt((1 / (input$ch9_n1 - 3)) + (1 / (input$ch9_n2 - 3))); z_stat <- (z1 - z2) / se_diff; p_val <- 2 * (1 - pnorm(abs(z_stat))); data.frame(Metric=c("z(1)", "z(2)", "SE(Z(diff))", "Z(diff) Test Stat", "Z(diff) LCL (95%)", "Z(diff) UCL (95%)", "Prob.", "p-value"), Value=c(z1, z2, se_diff, z_stat, z_stat - se_diff, z_stat + se_diff, p_val, p_val)) })
